//! CUA-S1-FORMS through the Rust SDK, against its reference goldens.
//!
//! `fixtures/models/cua-s1-forms/` commits the scorer's `model_metadata.json`;
//! its ONNX export is regenerated by `./integration-tests/download.sh
//! cua-s1-forms`, never committed. Every case of
//! `fixtures/choice/cases/forms.json` goes through `ModelLoader` and
//! `XybridModel::run`, the route an application takes, and must match
//! `fixtures/choice/goldens/forms.json`:
//!
//! - G0: the candidates in E order, with their fixed flags;
//! - G1: logits and scores within the bounds `provenance.json` freezes, and
//!   the reference's best candidate unless its margin is a near tie.
//!
//! The scored test skips when the export or ONNX Runtime is missing, unless
//! `XYBRID_REQUIRE_MODELS` is set, where it fails instead.

use integration_tests::fixtures;
use serde::Deserialize;
use xybrid_core::testing::model_fixtures::{models_required, staged_artifact, ENV_REQUIRE_MODELS};
use xybrid_sdk::ir::{Envelope, EnvelopeKind};
use xybrid_sdk::{Choice, ModelLoader};

#[derive(Deserialize)]
struct Cases {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    id: String,
    context: String,
    choices: Vec<Choice>,
}

#[derive(Deserialize)]
struct Goldens {
    cases: Vec<Golden>,
}

#[derive(Deserialize)]
struct Golden {
    id: String,
    candidates: Vec<Candidate>,
    logits: Vec<f64>,
    scores: Vec<f64>,
    best: usize,
    margin: f64,
}

#[derive(Deserialize)]
struct Candidate {
    id: String,
    fixed: bool,
}

#[derive(Deserialize)]
struct Provenance {
    gates: Gates,
}

#[derive(Deserialize)]
struct Gates {
    forms: FormsGates,
}

#[derive(Deserialize)]
struct FormsGates {
    status: String,
    g1: G1Bounds,
}

#[derive(Deserialize)]
struct G1Bounds {
    max_abs_logit: f64,
    max_abs_score: f64,
    near_tie_margin: f64,
}

fn read_json<T: for<'de> Deserialize<'de>>(relative: &str) -> T {
    let path = fixtures::fixtures_dir().join(relative);
    let text =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {}: {e}", path.display()))
}

/// Whether ONNX Runtime can run here: it is linked in on Apple platforms and
/// loaded from `ORT_DYLIB_PATH` elsewhere. Without it the scored test skips,
/// unless models are required, where it fails instead.
fn onnx_runtime() -> bool {
    let available = cfg!(any(target_os = "macos", target_os = "ios"))
        || std::env::var_os("ORT_DYLIB_PATH")
            .is_some_and(|path| std::path::Path::new(&path).is_file());
    if !available {
        assert!(
            !models_required(),
            "{ENV_REQUIRE_MODELS} is set but ONNX Runtime is not loadable; set ORT_DYLIB_PATH"
        );
        eprintln!("Skipping: ONNX Runtime is not loadable (set ORT_DYLIB_PATH)");
    }
    available
}

#[test]
fn the_forms_metadata_carries_the_pinned_spec() {
    let metadata: serde_json::Value = read_json("models/cua-s1-forms/model_metadata.json");
    let spec: serde_json::Value = read_json("choice/specs/cua-s1-forms.json");
    assert_eq!(metadata["execution_template"]["type"], "ChoiceScorer");
    assert_eq!(metadata["execution_template"]["scorer"], spec);
    assert_eq!(metadata["metadata"]["task"], "decision");
}

#[test]
fn forms_cases_match_the_reference_through_the_sdk() {
    let Some(onnx) = staged_artifact("cua-s1-forms", "cua-s1-forms.onnx") else {
        return;
    };
    if !onnx_runtime() {
        return;
    }
    let gates = read_json::<Provenance>("choice/provenance.json")
        .gates
        .forms;
    assert_eq!(
        gates.status, "frozen",
        "the FORMS bounds were measured and frozen; loosening them needs a justification, not a status change"
    );
    let bounds = gates.g1;

    let model = ModelLoader::from_directory(
        onnx.parent()
            .expect("the export sits in its model directory"),
    )
    .expect("the committed metadata parses")
    .load()
    .expect("the scorer loads");
    assert!(model.is_choice_scorer());
    let fixed: Vec<String> = model.fixed_choices().into_iter().map(|c| c.id).collect();
    assert_eq!(fixed, ["check", "click", "skip"]);
    model.warmup().expect("the scorer warms up");

    let cases = read_json::<Cases>("choice/cases/forms.json").cases;
    let goldens = read_json::<Goldens>("choice/goldens/forms.json").cases;
    assert_eq!(cases.len(), goldens.len());

    let (mut worst_logit, mut worst_score) = (0.0_f64, 0.0_f64);
    let mut exempt = Vec::new();
    for (case, golden) in cases.into_iter().zip(goldens) {
        assert_eq!(case.id, golden.id, "cases and goldens out of order");
        let request = Envelope::choice_request(
            Envelope::new(EnvelopeKind::Text(case.context)),
            case.choices,
        );
        let result = model
            .run(&request, None)
            .unwrap_or_else(|error| panic!("{}: {error}", case.id));
        let scores = result
            .choice_scores()
            .unwrap_or_else(|| panic!("{}: no choice scores", case.id));

        // G0: the candidates, in E order.
        let candidates: Vec<(&str, bool)> = scores
            .entries
            .iter()
            .map(|entry| (entry.id.as_str(), entry.fixed))
            .collect();
        let expected: Vec<(&str, bool)> = golden
            .candidates
            .iter()
            .map(|candidate| (candidate.id.as_str(), candidate.fixed))
            .collect();
        assert_eq!(candidates, expected, "{}", case.id);

        // G1: the numbers.
        for (index, entry) in scores.entries.iter().enumerate() {
            let logit = (f64::from(entry.logit) - golden.logits[index]).abs();
            let score = (f64::from(entry.score) - golden.scores[index]).abs();
            assert!(
                logit <= bounds.max_abs_logit,
                "{} candidate {index}: |Δlogit| {logit:.3e} > {:.1e}",
                case.id,
                bounds.max_abs_logit
            );
            assert!(
                score <= bounds.max_abs_score,
                "{} candidate {index}: |Δscore| {score:.3e} > {:.1e}",
                case.id,
                bounds.max_abs_score
            );
            worst_logit = worst_logit.max(logit);
            worst_score = worst_score.max(score);
        }
        if golden.margin < bounds.near_tie_margin {
            exempt.push(case.id.clone());
        } else {
            assert_eq!(scores.best(), Some(golden.best), "{}: argmax", case.id);
        }
    }
    eprintln!(
        "forms G1 through the SDK: max |Δlogit| {worst_logit:.3e}, max |Δscore| {worst_score:.3e}; \
         argmax exempt (margin < {}): {exempt:?}",
        bounds.near_tie_margin
    );
    assert_eq!(exempt, ["tie-duplicate-text", "near-tie-telephone"]);
}
